//! Shared vectors for `core/hashing`: generated by replaying the upstream
//! `spark-token-primitives` crate (protohash, transfer manifest, quote
//! envelope, token invoice, token-transaction V3 conversion + protohash),
//! consumed byte-for-byte by the TypeScript implementation.
//!
//! The `hashstructure` section is upstream-pinned constants (Go
//! `spark/common/hashstructure` test vectors plus the crate's own unit-test
//! pins) — the upstream Rust `Hasher` is crate-private, so those inputs and
//! expected digests are fixed here and only replayed by the TypeScript side.
//!
//! `SPARK_WRITE_VECTORS=1 cargo test --test hashing` regenerates
//! `vectors/hashing.json`; otherwise the test asserts the stored file is
//! identical to what the pinned upstream revision produces.

#![allow(
    unused_crate_dependencies,
    clippy::tests_outside_test_module,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::missing_panics_doc,
    clippy::cast_possible_truncation,
    reason = "test code"
)]

use std::path::{Path, PathBuf};

use prost::Message;
use prost_reflect::DynamicMessage;
use prost_types::Timestamp;
use serde_json::{Value, json};
use spark_token_primitives::proto::spark::{
    self, DelegationIntent, TransferManifest, TransferPackage,
};
use spark_token_primitives::proto::spark_token::{
    self, FinalTokenOutput, FinalTokenTransaction, PartialTokenOutput, PartialTokenTransaction,
    TokenOutput, TokenTransaction, TokenTransactionMetadata, final_token_transaction,
    partial_token_transaction, token_transaction,
};
use spark_token_primitives::protohash::{DESCRIPTOR_POOL, hash_proto};
use spark_token_primitives::{
    FinalizeTokenInvoiceRequest, PrepareTokenInvoiceRequest, coop_exit_target,
    finalize_token_invoice, hash_final_token_transaction, hash_partial_token_transaction,
    hash_transfer_manifest, prepare_token_invoice, quote_envelope_digest, receive_attestor_target,
    send_target, static_deposit_target,
};

mod common;
use common::UPSTREAM_REV;

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../vectors")
        .canonicalize()
        .unwrap()
}

fn header(source: &str) -> Value {
    json!({
        "source": source,
        "upstream": format!("buildonspark/spark@{UPSTREAM_REV}"),
        "note": "Test vectors only. Never use these keys for funds.",
    })
}

fn write_or_check(name: &str, document: &Value) {
    let path = vectors_dir().join(name);
    if std::env::var_os("SPARK_WRITE_VECTORS").is_some() {
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&document).unwrap() + "\n",
        )
        .unwrap();
        return;
    }
    let stored: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    check_document(&stored, document);
}

// Protobuf map fields encode in arbitrary order, so hex blobs carrying a
// map-bearing message (e.g. TransferPackage.key_tweak_package) differ between
// runs for the same logical message. Check mode decodes every blob field with
// its descriptor and compares messages semantically; all scalar fields,
// digests, and error strings must match exactly.
fn blob_descriptor<'a>(section: &str, field: &str, case: &'a Value) -> Option<&'a str> {
    match (section, field) {
        ("protohash", "messageHex") => case["typeName"].as_str(),
        ("tokenTransactionV3", "transactionHex") => Some("spark_token.TokenTransaction"),
        ("tokenTransactionV3", "partialTransactionHex")
        | ("partialTokenTransaction", "messageHex") => Some("spark_token.PartialTokenTransaction"),
        ("tokenTransactionV3", "finalTransactionHex") | ("finalTokenTransaction", "messageHex") => {
            Some("spark_token.FinalTokenTransaction")
        }
        ("transferManifest", "manifestHex") => Some("spark.TransferManifest"),
        ("tokenInvoice" | "finalizeTokenInvoice", "fieldsBytesHex") => {
            Some("spark.SparkInvoiceFields")
        }
        _ => None,
    }
}

fn decode_dynamic(type_name: &str, hex_bytes: &str) -> DynamicMessage {
    let descriptor = DESCRIPTOR_POOL.get_message_by_name(type_name).unwrap();
    DynamicMessage::decode(descriptor, hex::decode(hex_bytes).unwrap().as_slice()).unwrap()
}

fn check_document(stored: &Value, generated: &Value) {
    let stored = stored.as_object().unwrap();
    let generated = generated.as_object().unwrap();
    assert_eq!(stored.len(), generated.len(), "section count differs");
    for (section, cases) in generated {
        let stored_cases = &stored[section];
        match cases {
            Value::Array(cases) => {
                let stored_cases = stored_cases.as_array().unwrap();
                assert_eq!(stored_cases.len(), cases.len(), "{section} case count");
                for (generated_case, stored_case) in cases.iter().zip(stored_cases) {
                    check_case(section, generated_case, stored_case);
                }
            }
            _ => assert_eq!(stored_cases, cases, "section {section}"),
        }
    }
}

fn check_case(section: &str, generated: &Value, stored: &Value) {
    let generated_fields = generated.as_object().unwrap();
    let stored_fields = stored.as_object().unwrap();
    let name = generated["name"].as_str().unwrap_or("<unnamed>");
    assert_eq!(
        stored_fields.len(),
        generated_fields.len(),
        "{section}.{name} field count"
    );
    for (field, generated_value) in generated_fields {
        let stored_value = stored_fields
            .get(field)
            .unwrap_or_else(|| panic!("{section}.{name}: stored case lacks {field}"));
        if let Some(type_name) = blob_descriptor(section, field, generated) {
            assert_eq!(
                decode_dynamic(type_name, generated_value.as_str().unwrap()),
                decode_dynamic(type_name, stored_value.as_str().unwrap()),
                "{section}.{name}.{field} message mismatch",
            );
        } else {
            assert_eq!(stored_value, generated_value, "{section}.{name}.{field}");
        }
    }
}

fn key(byte: u8) -> Vec<u8> {
    let mut k = vec![0x02];
    k.extend(std::iter::repeat_n(byte, 32));
    k
}

// A real compressed secp256k1 pubkey: the TS port validates invoice receiver
// and sender keys on-curve, so these must be genuine points.
fn real_key(byte: u8) -> Vec<u8> {
    let secret = bitcoin::secp256k1::SecretKey::from_slice(&[byte; 32]).expect("in-range secret");
    bitcoin::secp256k1::PublicKey::from_secret_key(&bitcoin::key::Secp256k1::new(), &secret)
        .serialize()
        .to_vec()
}

fn bytes32(byte: u8) -> Vec<u8> {
    vec![byte; 32]
}

fn uuid_bytes(byte: u8) -> Vec<u8> {
    vec![byte; 16]
}

fn hash_dynamic(type_name: &str, bytes: &[u8]) -> Result<Vec<u8>, String> {
    let descriptor = DESCRIPTOR_POOL
        .get_message_by_name(type_name)
        .ok_or_else(|| format!("no descriptor for {type_name}"))?;
    let message = DynamicMessage::decode(descriptor, bytes)
        .map_err(|e| format!("decode {type_name}: {e}"))?;
    hash_proto(&message)
        .map(|h| h.to_vec())
        .map_err(|e| e.to_string())
}

