// ---------------------------------------------------------------------------
// protohash — real Spark messages hashed through the upstream crate.
// ---------------------------------------------------------------------------

fn protohash_cases() -> Vec<Value> {
    fn push<M: Message>(cases: &mut Vec<Value>, name: &str, type_name: &str, message: &M) {
        let bytes = message.encode_to_vec();
        let result = hash_dynamic(type_name, &bytes);
        cases.push(match result {
            Ok(hash) => json!({
                "name": name,
                "typeName": type_name,
                "messageHex": hex::encode(&bytes),
                "expected": hex::encode(hash),
            }),
            Err(e) => json!({
                "name": name,
                "typeName": type_name,
                "messageHex": hex::encode(&bytes),
                "error": e,
            }),
        });
    }

    let mut cases = Vec::new();

    // Map + enum + nested message with inner map.
    push(
        &mut cases,
        "transfer_package_full",
        "spark.TransferPackage",
        &TransferPackage {
            key_tweak_package: [
                ("aa".to_owned(), vec![0x11u8; 16]),
                ("zz".to_owned(), vec![0x22u8; 4]),
            ]
            .into_iter()
            .collect(),
            hash_variant: spark::HashVariant::V2 as i32,
            delegation_intent: Some(DelegationIntent {
                grant_id: "11111111-1111-1111-1111-111111111111".into(),
                spender_identity_public_key: key(0xaa),
                total_amount_sats: 1234,
                receiver_amounts_sats: [
                    ("deadbeef".to_owned(), 1000u64),
                    ("cafe".to_owned(), 234u64),
                ]
                .into_iter()
                .collect(),
            }),
            ..Default::default()
        },
    );

    // Empty message: protohashes to the digest of an empty field list.
    push(
        &mut cases,
        "transfer_package_empty",
        "spark.TransferPackage",
        &TransferPackage::default(),
    );

    // TransferManifest exercises timestamps, repeated messages, enums and a
    // nested oneof (ManifestAmount) — a fuller workout than a flat message.
    push(
        &mut cases,
        "transfer_manifest",
        "spark.TransferManifest",
        &sample_manifest(),
    );

    // TokenTransaction v3: oneof inputs, repeated outputs, enum, Timestamp.
    push(
        &mut cases,
        "token_transaction_v3_mint",
        "spark_token.TokenTransaction",
        &sample_token_tx_mint(),
    );

    // Scalar-heavy message: strings, bools, u32, bytes.
    push(
        &mut cases,
        "token_create_input",
        "spark_token.TokenCreateInput",
        &spark_token::TokenCreateInput {
            issuer_public_key: key(0x07),
            token_name: "Spark Test Token".into(),
            token_ticker: "STT".into(),
            decimals: 8,
            max_supply: vec![0xff; 16],
            is_freezable: true,
            creation_entity_public_key: Some(key(0x09)),
            extra_metadata: Some(b"meta".to_vec()),
        },
    );

    // Nested invoice fields: bytes id, oneof payment, optional message, string.
    push(
        &mut cases,
        "spark_invoice_fields_tokens",
        "spark.SparkInvoiceFields",
        &spark::SparkInvoiceFields {
            version: 1,
            id: uuid_bytes(0x11),
            memo: Some("pay me".into()),
            sender_public_key: Some(key(0x33)),
            expiry_time: Some(Timestamp {
                seconds: 1_800_000_000,
                nanos: 250_000_000,
            }),
            payment_type: Some(spark::spark_invoice_fields::PaymentType::TokensPayment(
                spark::TokensPayment {
                    token_identifier: Some(bytes32(0x44)),
                    amount: Some(vec![0x01, 0xe8]),
                },
            )),
        },
    );

    cases
}

