// ---------------------------------------------------------------------------
// Token transaction V3 — Go converts TokenTransaction → Partial/Final protos
// (protoconverter.ConvertV2TxShapeTo{Partial,Final}) and protohashes the
// result; the same conversion is mirrored here.
// ---------------------------------------------------------------------------

fn to_partial_output(o: &TokenOutput) -> PartialTokenOutput {
    PartialTokenOutput {
        owner_public_key: o.owner_public_key.clone(),
        withdraw_bond_sats: o.withdraw_bond_sats.unwrap_or_default(),
        withdraw_relative_block_locktime: o.withdraw_relative_block_locktime.unwrap_or_default(),
        token_identifier: o.token_identifier.clone().unwrap_or_default(),
        token_amount: o.token_amount.clone(),
    }
}

fn metadata(tx: &TokenTransaction) -> TokenTransactionMetadata {
    TokenTransactionMetadata {
        spark_operator_identity_public_keys: tx.spark_operator_identity_public_keys.clone(),
        network: tx.network,
        client_created_timestamp: tx.client_created_timestamp,
        validity_duration_seconds: tx.validity_duration_seconds.unwrap_or_default(),
        invoice_attachments: tx.invoice_attachments.clone(),
    }
}

fn to_partial(tx: &TokenTransaction) -> PartialTokenTransaction {
    let inputs = match &tx.token_inputs {
        Some(token_transaction::TokenInputs::MintInput(mint)) => Some(
            partial_token_transaction::TokenInputs::MintInput(spark_token::TokenMintInput {
                issuer_public_key: mint.issuer_public_key.clone(),
                token_identifier: mint.token_identifier.clone(),
            }),
        ),
        Some(token_transaction::TokenInputs::TransferInput(transfer)) => {
            Some(partial_token_transaction::TokenInputs::TransferInput(
                spark_token::TokenTransferInput {
                    outputs_to_spend: transfer.outputs_to_spend.clone(),
                },
            ))
        }
        Some(token_transaction::TokenInputs::CreateInput(create)) => Some(
            partial_token_transaction::TokenInputs::CreateInput(spark_token::TokenCreateInput {
                issuer_public_key: create.issuer_public_key.clone(),
                token_name: create.token_name.clone(),
                token_ticker: create.token_ticker.clone(),
                decimals: create.decimals,
                max_supply: create.max_supply.clone(),
                is_freezable: create.is_freezable,
                creation_entity_public_key: None,
                extra_metadata: create.extra_metadata.clone(),
            }),
        ),
        None => None,
    };
    PartialTokenTransaction {
        version: tx.version,
        token_transaction_metadata: Some(metadata(tx)),
        token_inputs: inputs,
        partial_token_outputs: tx.token_outputs.iter().map(to_partial_output).collect(),
        execute_before: tx.execute_before,
    }
}

fn to_final(tx: &TokenTransaction) -> FinalTokenTransaction {
    let inputs = match &tx.token_inputs {
        Some(token_transaction::TokenInputs::MintInput(mint)) => Some(
            final_token_transaction::TokenInputs::MintInput(mint.clone()),
        ),
        Some(token_transaction::TokenInputs::TransferInput(transfer)) => Some(
            final_token_transaction::TokenInputs::TransferInput(transfer.clone()),
        ),
        Some(token_transaction::TokenInputs::CreateInput(create)) => Some(
            final_token_transaction::TokenInputs::CreateInput(create.clone()),
        ),
        None => panic!("unknown token input type"),
    };
    FinalTokenTransaction {
        version: tx.version,
        token_transaction_metadata: Some(metadata(tx)),
        token_inputs: inputs,
        final_token_outputs: tx
            .token_outputs
            .iter()
            .map(|o| FinalTokenOutput {
                partial_token_output: Some(to_partial_output(o)),
                revocation_commitment: o.revocation_commitment.clone().unwrap_or_default(),
            })
            .collect(),
        execute_before: tx.execute_before,
    }
}

