fn token_v3_cases() -> Vec<Value> {
    let mut cases = Vec::new();
    for (name, tx) in [
        ("mint", sample_token_tx_mint()),
        ("transfer", sample_token_tx_transfer()),
        ("create", sample_token_tx_create()),
    ] {
        let tx_bytes = tx.encode_to_vec();
        let partial = to_partial(&tx);
        let final_tx = to_final(&tx);
        cases.push(json!({
            "name": format!("{name}_partial"),
            "transactionHex": hex::encode(&tx_bytes),
            "partial": true,
            "partialTransactionHex": hex::encode(partial.encode_to_vec()),
            "expected": hex::encode(hash_proto(&partial).unwrap()),
        }));
        cases.push(json!({
            "name": format!("{name}_final"),
            "transactionHex": hex::encode(&tx_bytes),
            "partial": false,
            "finalTransactionHex": hex::encode(final_tx.encode_to_vec()),
            "expected": hex::encode(hash_proto(&final_tx).unwrap()),
        }));
    }
    cases
}

// ---------------------------------------------------------------------------
// Direct hashing APIs taking protobuf bytes.
// ---------------------------------------------------------------------------

fn partial_and_final_cases() -> (Vec<Value>, Vec<Value>) {
    let partial_tx = to_partial(&sample_token_tx_transfer());
    let final_tx = to_final(&sample_token_tx_transfer());
    let partial_bytes = partial_tx.encode_to_vec();
    let final_bytes = final_tx.encode_to_vec();
    (
        vec![json!({
            "name": "transfer",
            "messageHex": hex::encode(&partial_bytes),
            "expected": hex::encode(hash_partial_token_transaction(partial_bytes).unwrap()),
        })],
        vec![json!({
            "name": "transfer",
            "messageHex": hex::encode(&final_bytes),
            "expected": hex::encode(hash_final_token_transaction(final_bytes).unwrap()),
        })],
    )
}

fn manifest_cases() -> Vec<Value> {
    let good = sample_manifest();
    let mut cases = vec![json!({
        "name": "valid_full",
        "manifestHex": hex::encode(good.encode_to_vec()),
        "expected": hex::encode(hash_transfer_manifest(good.encode_to_vec()).unwrap()),
    })];

    // A manifest needing canonicalization: out-of-order edges + sub-ms nanos.
    let mut unsorted = sample_manifest();
    unsorted.edges.reverse();
    if let Some(ts) = unsorted.transfer_expiry_time.as_mut() {
        ts.nanos = 123_456_789;
    }
    let unsorted_bytes = unsorted.encode_to_vec();
    cases.push(json!({
        "name": "unsorted_edges_subms_timestamp",
        "manifestHex": hex::encode(&unsorted_bytes),
        "expected": hex::encode(hash_transfer_manifest(unsorted_bytes).unwrap()),
    }));

    // Error cases — validation must reject before hashing.
    let mut bad_version = sample_manifest();
    bad_version.version = 2;
    let bad_version_bytes = bad_version.encode_to_vec();
    cases.push(json!({
        "name": "unsupported_version",
        "manifestHex": hex::encode(&bad_version_bytes),
        "error": hash_transfer_manifest(bad_version_bytes).unwrap_err().to_string(),
    }));

    let mut epoch = sample_manifest();
    epoch.transfer_expiry_time = Some(Timestamp {
        seconds: 0,
        nanos: 0,
    });
    let epoch_bytes = epoch.encode_to_vec();
    cases.push(json!({
        "name": "epoch_timestamp",
        "manifestHex": hex::encode(&epoch_bytes),
        "error": hash_transfer_manifest(epoch_bytes).unwrap_err().to_string(),
    }));

    let mut zero_amount = sample_manifest();
    zero_amount.edges[0].amount = Some(spark::ManifestAmount {
        amount: Some(spark::manifest_amount::Amount::Sats(0)),
    });
    let zero_amount_bytes = zero_amount.encode_to_vec();
    cases.push(json!({
        "name": "zero_amount_edge",
        "manifestHex": hex::encode(&zero_amount_bytes),
        "error": hash_transfer_manifest(zero_amount_bytes).unwrap_err().to_string(),
    }));

    let mut bad_network = sample_manifest();
    bad_network.network = 0;
    let bad_network_bytes = bad_network.encode_to_vec();
    cases.push(json!({
        "name": "unspecified_network",
        "manifestHex": hex::encode(&bad_network_bytes),
        "error": hash_transfer_manifest(bad_network_bytes).unwrap_err().to_string(),
    }));

    cases
}

// ---------------------------------------------------------------------------
// Quote envelopes and targets.
// ---------------------------------------------------------------------------

fn quote_cases() -> (Vec<Value>, Vec<Value>) {
    let payment_hash = bytes32(0x5a);
    let leaf_set_hash = bytes32(0x6b);
    let manifest_hash = bytes32(0x7c);
    let txid = bytes32(0x8d);
    let withdrawal_address = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";

    let targets = vec![
        json!({
            "name": "receive_attestor",
            "kind": "receiveAttestor",
            "paymentHashHex": hex::encode(&payment_hash),
            "expected": hex::encode(receive_attestor_target(payment_hash.clone()).unwrap()),
        }),
        json!({
            "name": "send",
            "kind": "send",
            "paymentHashHex": hex::encode(&payment_hash),
            "expected": hex::encode(send_target(payment_hash).unwrap()),
        }),
        json!({
            "name": "coop_exit",
            "kind": "coopExit",
            "withdrawalAddress": withdrawal_address,
            "leafSetHashHex": hex::encode(&leaf_set_hash),
            "expected": hex::encode(coop_exit_target(withdrawal_address.to_owned(), leaf_set_hash.clone()).unwrap()),
        }),
        json!({
            "name": "coop_exit_uppercase_address",
            "kind": "coopExit",
            "withdrawalAddress": withdrawal_address.to_uppercase(),
            "leafSetHashHex": hex::encode(&leaf_set_hash),
            "expected": hex::encode(coop_exit_target(withdrawal_address.to_uppercase(), leaf_set_hash).unwrap()),
        }),
        json!({
            "name": "coop_exit_not_segwit",
            "kind": "coopExit",
            "withdrawalAddress": "1BoatSLRHtKNngkdXEeobR76b53LETtpyT",
            "leafSetHashHex": hex::encode(bytes32(0x6b)),
            "expected": hex::encode(coop_exit_target("1BoatSLRHtKNngkdXEeobR76b53LETtpyT".to_owned(), bytes32(0x6b)).unwrap()),
        }),
        json!({
            "name": "static_deposit",
            "kind": "staticDeposit",
            "txidHex": hex::encode(&txid),
            "vout": 3u32,
            "expected": hex::encode(static_deposit_target(txid.clone(), 3).unwrap()),
        }),
    ];

    let mut envelopes = Vec::new();
    let attestor_receive = receive_attestor_target(bytes32(0x5a)).unwrap();
    let issuer_empty: Vec<u8> = Vec::new();
    for (name, network, reason, role, target) in [
        ("receive_issuer", 1u32, 1u32, 1u32, issuer_empty.clone()),
        ("receive_attestor", 1, 1, 2, attestor_receive.clone()),
        (
            "send_attestor_regtest",
            2,
            2,
            2,
            send_target(bytes32(0x5a)).unwrap(),
        ),
        (
            "coop_exit_attestor",
            1,
            3,
            2,
            coop_exit_target(withdrawal_address.to_owned(), bytes32(0x6b)).unwrap(),
        ),
        (
            "static_deposit_attestor",
            2,
            4,
            2,
            static_deposit_target(bytes32(0x8d), 0).unwrap(),
        ),
    ] {
        envelopes.push(json!({
            "name": name,
            "network": network,
            "manifestHashHex": hex::encode(&manifest_hash),
            "reason": reason,
            "role": role,
            "targetHex": hex::encode(&target),
            "expected": hex::encode(
                quote_envelope_digest(network, manifest_hash.clone(), reason, role, target)
                    .unwrap(),
            ),
        }));
    }
    for (name, network, reason, role, target) in [
        ("bad_network", 0u32, 1u32, 1u32, issuer_empty.clone()),
        ("bad_reason", 1, 0, 1, issuer_empty.clone()),
        ("bad_role", 1, 1, 0, issuer_empty.clone()),
        ("attestor_empty_target", 1, 1, 2, issuer_empty.clone()),
    ] {
        envelopes.push(json!({
            "name": name,
            "network": network,
            "manifestHashHex": hex::encode(&manifest_hash),
            "reason": reason,
            "role": role,
            "targetHex": hex::encode(&target),
            "error": quote_envelope_digest(network, manifest_hash.clone(), reason, role, target)
                .unwrap_err()
                .to_string(),
        }));
    }
    (targets, envelopes)
}

// ---------------------------------------------------------------------------
// Token invoice prepare/finalize.
// ---------------------------------------------------------------------------

fn invoice_cases() -> (Vec<Value>, Vec<Value>) {
    let receiver = real_key(0x61);
    let unsigned = prepare_token_invoice(PrepareTokenInvoiceRequest {
        receiver_identity_public_key: receiver.clone(),
        network: spark::Network::Regtest as u32,
        token_identifier: Some(bytes32(0x70)),
        token_amount: Some(vec![0x01, 0xe8]),
        memo: Some("invoice memo".into()),
        sender_spark_address: None,
        expiry_time_unix_millis: Some(1_800_000_123_456),
        invoice_id: Some(uuid_bytes(0x99)),
    })
    .unwrap();

    // A sender address must parse; mint one via an unsigned address.
    let sender_address = prepare_token_invoice(PrepareTokenInvoiceRequest {
        receiver_identity_public_key: real_key(0x62),
        network: spark::Network::Regtest as u32,
        token_identifier: None,
        token_amount: None,
        memo: None,
        sender_spark_address: None,
        expiry_time_unix_millis: None,
        invoice_id: Some(uuid_bytes(0x88)),
    })
    .unwrap()
    .unsigned_spark_address;

    let with_sender = prepare_token_invoice(PrepareTokenInvoiceRequest {
        receiver_identity_public_key: receiver.clone(),
        network: spark::Network::Regtest as u32,
        token_identifier: None,
        token_amount: None,
        memo: None,
        sender_spark_address: Some(sender_address),
        expiry_time_unix_millis: None,
        invoice_id: Some(uuid_bytes(0x77)),
    })
    .unwrap();

    let prepares = vec![
        json!({
            "name": "full",
            "receiverIdentityPublicKey": hex::encode(&receiver),
            "network": "regtest",
            "tokenIdentifierHex": hex::encode(bytes32(0x70)),
            "tokenAmountHex": "01e8",
            "memo": "invoice memo",
            "expiryTimeUnixMillis": 1_800_000_123_456u64,
            "invoiceIdHex": hex::encode(uuid_bytes(0x99)),
            "fieldsBytesHex": hex::encode(&unsigned.spark_invoice_fields_bytes),
            "invoiceHashHex": hex::encode(&unsigned.spark_invoice_hash),
            "unsignedAddress": unsigned.unsigned_spark_address,
        }),
        json!({
            "name": "with_sender",
            "receiverIdentityPublicKey": hex::encode(&receiver),
            "network": "regtest",
            "senderAddress": with_sender_request_address(),
            "invoiceIdHex": hex::encode(uuid_bytes(0x77)),
            "fieldsBytesHex": hex::encode(&with_sender.spark_invoice_fields_bytes),
            "invoiceHashHex": hex::encode(&with_sender.spark_invoice_hash),
            "unsignedAddress": with_sender.unsigned_spark_address,
        }),
    ];

    let signature = vec![0x55u8; 64];
    let signed_address = finalize_token_invoice(FinalizeTokenInvoiceRequest {
        receiver_identity_public_key: receiver.clone(),
        network: spark::Network::Regtest as u32,
        spark_invoice_fields_bytes: unsigned.spark_invoice_fields_bytes.clone(),
        signature: Some(signature.clone()),
    })
    .unwrap();
    let unsigned_address = finalize_token_invoice(FinalizeTokenInvoiceRequest {
        receiver_identity_public_key: receiver.clone(),
        network: spark::Network::Regtest as u32,
        spark_invoice_fields_bytes: unsigned.spark_invoice_fields_bytes.clone(),
        signature: None,
    })
    .unwrap();

    let finalizes = vec![
        json!({
            "name": "signed",
            "receiverIdentityPublicKey": hex::encode(&receiver),
            "network": "regtest",
            "fieldsBytesHex": hex::encode(&unsigned.spark_invoice_fields_bytes),
            "signatureHex": hex::encode(&signature),
            "address": signed_address,
        }),
        json!({
            "name": "unsigned",
            "receiverIdentityPublicKey": hex::encode(&receiver),
            "network": "regtest",
            "fieldsBytesHex": hex::encode(&unsigned.spark_invoice_fields_bytes),
            "signatureHex": null,
            "address": unsigned_address,
        }),
    ];
    (prepares, finalizes)
}

// The sender address used by `with_sender` must be reproducible: recompute it.
fn with_sender_request_address() -> String {
    prepare_token_invoice(PrepareTokenInvoiceRequest {
        receiver_identity_public_key: real_key(0x62),
        network: spark::Network::Regtest as u32,
        token_identifier: None,
        token_amount: None,
        memo: None,
        sender_spark_address: None,
        expiry_time_unix_millis: None,
        invoice_id: Some(uuid_bytes(0x88)),
    })
    .unwrap()
    .unsigned_spark_address
}

#[test]
fn hashing_vectors() {
    let (partial_cases, final_cases) = partial_and_final_cases();
    let (targets, envelopes) = quote_cases();
    let (prepares, finalizes) = invoice_cases();

    let document = json!({
        "header": header("upstream spark-token-primitives (protohash, manifests, quote envelopes, token invoices, V3 conversion mirroring spark/so/protoconverter); hashstructure is upstream-pinned Go/Rust constants"),
        "hashstructure": hashstructure_cases(),
        "protohash": protohash_cases(),
        "tokenTransactionV3": token_v3_cases(),
        "partialTokenTransaction": partial_cases,
        "finalTokenTransaction": final_cases,
        "transferManifest": manifest_cases(),
        "quoteTargets": targets,
        "quoteEnvelope": envelopes,
        "tokenInvoice": prepares,
        "finalizeTokenInvoice": finalizes,
    });
    write_or_check("hashing.json", &document);
}
